CREATE FUNCTION touch_updated() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name))>0), owner text NOT NULL, data_review_due date NOT NULL, retention_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX project_name ON projects(lower(name));
CREATE TABLE cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, external_id text, title text NOT NULL CHECK(length(trim(title))>0), section text NOT NULL DEFAULT '', priority text NOT NULL DEFAULT 'Medium' CHECK(priority IN ('Low','Medium','High','Critical')), test_type text NOT NULL DEFAULT 'Functional', refs text NOT NULL DEFAULT '', steps text NOT NULL DEFAULT '', expected text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1 CHECK(version>0), approved_by text, approved_at timestamptz, reviewed_on date NOT NULL DEFAULT current_date, source_data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,external_id));
CREATE TABLE runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, name text NOT NULL, build text NOT NULL, environment text NOT NULL, due_on date NOT NULL, state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')), closed_by text, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,name));
CREATE TABLE run_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES runs, case_id uuid NOT NULL REFERENCES cases, snapshot jsonb NOT NULL, assignee text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,case_id));
CREATE TABLE results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seq bigint GENERATED ALWAYS AS IDENTITY UNIQUE, run_case_id uuid NOT NULL REFERENCES run_cases, status text NOT NULL CHECK(status IN ('passed','failed','blocked','retest')), evidence text NOT NULL CHECK(length(trim(evidence))>0), note text NOT NULL DEFAULT '', actor text NOT NULL CHECK(length(trim(actor))>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE defects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_case_id uuid NOT NULL REFERENCES run_cases, title text NOT NULL, external_ref text NOT NULL, owner text NOT NULL, severity text NOT NULL CHECK(severity IN ('Low','Medium','High','Critical')), state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')), resolution text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE activity(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor text NOT NULL, action text NOT NULL, record_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'History is append-only'; END $$;
CREATE TRIGGER immutable_results BEFORE UPDATE OR DELETE ON results FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER immutable_activity BEFORE UPDATE OR DELETE ON activity FOR EACH ROW EXECUTE FUNCTION immutable_record();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['projects','cases','runs','run_cases','defects'] LOOP EXECUTE format('CREATE TRIGGER touch BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated()',t); END LOOP; FOREACH t IN ARRAY ARRAY['projects','cases','runs','run_cases','results','defects','activity'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON %I FROM PUBLIC',t); END LOOP; END $$;
CREATE VIEW execution_status AS SELECT rc.id,rc.run_id,rc.case_id,r.project_id,r.name AS run,r.build,r.environment,r.due_on,r.state,rc.snapshot->>'title' AS title,rc.snapshot->>'priority' AS priority,rc.snapshot->>'refs' AS refs,(rc.snapshot->>'version')::int AS version,rc.assignee,COALESCE(x.status,'untested') AS status,x.evidence,x.actor,x.created_at AS tested_at,COALESCE(d.open_defects,0) AS open_defects FROM run_cases rc JOIN runs r ON r.id=rc.run_id LEFT JOIN LATERAL (SELECT * FROM results WHERE run_case_id=rc.id ORDER BY seq DESC LIMIT 1) x ON true LEFT JOIN LATERAL (SELECT count(*)::int AS open_defects FROM defects WHERE run_case_id=rc.id AND state='open') d ON true;
CREATE VIEW release_readiness AS SELECT r.id,r.name,r.build,r.environment,r.due_on,r.state,count(e.id)::int AS total,count(e.id) FILTER(WHERE e.status='passed')::int AS passed,count(e.id) FILTER(WHERE e.status<>'passed')::int AS remaining,COALESCE(sum(e.open_defects),0)::int AS open_defects,CASE WHEN count(e.id)>0 AND count(e.id) FILTER(WHERE e.status<>'passed')=0 AND COALESCE(sum(e.open_defects),0)=0 THEN 'ready for human review' ELSE 'hold' END AS decision FROM runs r LEFT JOIN execution_status e ON e.run_id=r.id GROUP BY r.id;
CREATE VIEW case_coverage AS SELECT c.id,p.name AS project,c.title,c.priority,c.refs,c.version,c.approved_by,c.reviewed_on,count(rc.id)::int AS runs, max(x.created_at) AS last_result FROM cases c JOIN projects p ON p.id=c.project_id LEFT JOIN run_cases rc ON rc.case_id=c.id LEFT JOIN results x ON x.run_case_id=rc.id GROUP BY c.id,p.name;
CREATE VIEW attention AS SELECT 'run overdue'::text AS issue,name AS item,due_on AS due FROM runs WHERE state='open' AND due_on<current_date UNION ALL SELECT 'case approval needed',title,reviewed_on FROM cases WHERE approved_by IS NULL UNION ALL SELECT 'case review stale',title,reviewed_on+90 FROM cases WHERE reviewed_on<current_date-90 UNION ALL SELECT 'test data review due',name,data_review_due FROM projects WHERE data_review_due<=current_date UNION ALL SELECT 'open defect',title,created_at::date FROM defects WHERE state='open';
CREATE VIEW compliance_findings AS SELECT 'IPP9-review'::text AS rule,name AS item,'Review test-data purpose and retention'::text AS action FROM projects WHERE data_review_due<=current_date OR retention_note='' UNION ALL SELECT 'INTERNAL-case-approval',title,'Approve current case version before adding it to a run' FROM cases WHERE approved_by IS NULL UNION ALL SELECT 'INTERNAL-traceability',title,'Record a requirement or risk reference' FROM cases WHERE refs='' UNION ALL SELECT 'INTERNAL-failure-tracking',e.title,'Record a defect reference for the failed execution' FROM execution_status e WHERE e.status='failed' AND NOT EXISTS(SELECT 1 FROM defects d WHERE d.run_case_id=e.id);
REVOKE ALL ON execution_status,release_readiness,case_coverage,attention,compliance_findings FROM PUBLIC;
